import{_ as o,o as r,c as i,a2 as a}from"./chunks/framework.ClgMjOt7.js";const g=JSON.parse('{"title":"作品閲覧","description":"イラスト、マンガ、小説、うごイラ、ショートフィードの表示・閲覧機能","frontmatter":{"title":"作品閲覧","description":"イラスト、マンガ、小説、うごイラ、ショートフィードの表示・閲覧機能"},"headers":[],"relativePath":"features/browse.md","filePath":"features/browse.md","lastUpdated":1786166106000}'),l={name:"features/browse.md"};function t(c,e,n,d,s,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="作品閲覧" tabindex="-1">作品閲覧 <a class="header-anchor" href="#作品閲覧" aria-label="Permalink to &quot;作品閲覧&quot;">​</a></h1><p>イラスト・マンガ・小説・うごイラ（アニメーション）の各メディアに対応した閲覧画面を提供します。</p><hr><h2 id="タブおよびフィード構成" tabindex="-1">タブおよびフィード構成 <a class="header-anchor" href="#タブおよびフィード構成" aria-label="Permalink to &quot;タブおよびフィード構成&quot;">​</a></h2><ul><li><strong>おすすめ (Home)</strong>: 関連イラストおよび推奨コンテンツの表示。</li><li><strong>フォロー中</strong>: フォロー中ユーザーの最新作品タイムライン。</li><li><strong>ランキング (<code>RankingScreen</code>)</strong>: デイリー、ウィークリー、マンスリー、R-18、女子人気、男子人気などの各ランキング。</li><li><strong>ショートフィード (<code>ShortsFeedScreen</code>)</strong>: フルスクリーンでの縦スワイプ閲覧。</li><li><strong>小説 (<code>NovelScreen</code>)</strong>: 小説作品一覧および本文リーダー。</li></ul><hr><h2 id="コンテンツ別ビューア機能" tabindex="-1">コンテンツ別ビューア機能 <a class="header-anchor" href="#コンテンツ別ビューア機能" aria-label="Permalink to &quot;コンテンツ別ビューア機能&quot;">​</a></h2><h3 id="_1-イラスト・マンガビューア-imageviewerscreen" tabindex="-1">1. イラスト・マンガビューア (<code>ImageViewerScreen</code>) <a class="header-anchor" href="#_1-イラスト・マンガビューア-imageviewerscreen" aria-label="Permalink to &quot;1. イラスト・マンガビューア (`ImageViewerScreen`)&quot;">​</a></h3><ul><li><strong>高解像度ズーム</strong>: ピンチ操作による拡大・縮小。</li><li><strong>複数ページ閲覧</strong>: マルチページ作品のスライド切り替えおよび見開き表示。</li><li><strong>解像度制御</strong>: <code>AppSettings</code> の各種品質設定に連動。 <ul><li><code>feedPreviewQuality</code>: フィードサムネイル品質 (<code>low</code> / <code>high</code>)</li><li><code>illustDetailQuality</code>: イラスト詳細表示画質 (<code>medium</code> / <code>high</code> / <code>original</code>)</li><li><code>fullscreenQuality</code>: フルスクリーンビューア画質 (<code>high</code> / <code>original</code>)</li></ul></li></ul><h3 id="_2-うごイラ再生-ugoiraartwork" tabindex="-1">2. うごイラ再生 (<code>UgoiraArtwork</code>) <a class="header-anchor" href="#_2-うごイラ再生-ugoiraartwork" aria-label="Permalink to &quot;2. うごイラ再生 (`UgoiraArtwork`)&quot;">​</a></h3><ul><li>Pixiv のうごイラ Zip アーカイブ（JPEG/PNG フレームデータ）をダウンロードし、<code>UgoiraMetadata</code> のフレーム遅延情報に基づいてアニメーション生成・再生。</li><li>一時停止、フレーム送り、繰り返し再生の制御に対応。</li></ul><h3 id="_3-小説リーダー-novelscreen" tabindex="-1">3. 小説リーダー (<code>NovelScreen</code>) <a class="header-anchor" href="#_3-小説リーダー-novelscreen" aria-label="Permalink to &quot;3. 小説リーダー (`NovelScreen`)&quot;">​</a></h3><ul><li><strong>レイアウト設定</strong>: 縦書き（和文表示）および横書きの切り替え。</li><li><strong>読書カスタマイズ</strong>: フォントサイズ、行間、背景テーマ（ホワイト、セピア、ダーク）の選択。</li><li><strong>挿絵埋め込み</strong>: 文中の <code>[pixivimage:id]</code> 形式の挿絵コードを解析し、インライン/ポップアップ表示。</li></ul><hr><h2 id="ユーザープロフィール-userprofilescreen" tabindex="-1">ユーザープロフィール (<code>UserProfileScreen</code>) <a class="header-anchor" href="#ユーザープロフィール-userprofilescreen" aria-label="Permalink to &quot;ユーザープロフィール (`UserProfileScreen`)&quot;">​</a></h2><p>作者名をタップするとユーザー詳細画面を表示します。</p><ul><li>投稿イラスト・マンガ・小説のタブ分け表示</li><li>公開ブックマーク作品</li><li>フォロー / フォロー解除切り替え（公開・非公開の選択）</li><li>ユーザーのミュート登録</li></ul>',17)])])}const _=o(l,[["render",t]]);export{g as __pageData,_ as default};
